      {
        "id": "B",
        "text": "Migrate the database to Amazon RDS with Multi-AZ enabled"
      },
      {
        "id": "C",
        "text": "Move both NAT gateways into AZ-A behind an Application Load Balancer"
      },
      {
        "id": "D",
        "text": "Replace the NAT gateways with a single larger NAT instance"
      },
      {
        "id": "E",
        "text": "Take nightly EBS snapshots of the database EC2 instance"
      }
